// recipe: remote-panel-heart
// args: none
// returns: ok, open, stage, target, heartRate, heartProg, arrested, critical, error, detail
//
// Reads the host's remote medical panel state: which body it displays and what that display body's own heart reads. It exists
// because the panel's alarm and flatline both hang off the DISPLAYED body's heart, and the only way to tell "the cue did not
// fire" from "the display never read a stop" is to look at the number the cue reads. Every read tries the PROPERTY first and
// falls back to the FIELD: `heartRate` and `heartProg` are fields while `inCardiacArrest` is a property, and a property-only
// read answered 0 for both fields (2026-11-02).
//
// ONE LINE ON PURPOSE: the client's evaluator takes one top-level expression.
((System.Func<string>)(() => { var stage = "start"; try { var flags = System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic; var instance = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic; var assemblies = System.AppDomain.CurrentDomain.GetAssemblies(); var view = (System.Type)null; for (var i = 0; i < assemblies.Length; i++) { try { view = assemblies[i].GetType("CasualtiesUnknownOnline.GameAdapter.Character.RemoteMedicalView", false); } catch { view = null; } if (view != null) { break; } } stage = "type"; if (view == null) { return "{\"ok\":false,\"stage\":\"type\",\"error\":\"view-type-missing\"}"; } var display = view.GetProperty("DisplayBody", flags).GetValue(null, null); stage = "display"; if (display == null) { return "{\"ok\":true,\"stage\":\"display\",\"open\":false}"; } var type = display.GetType(); var rateProperty = type.GetProperty("heartRate", instance); var rateField = type.GetField("heartRate", instance); var progProperty = type.GetProperty("heartProg", instance); var progField = type.GetField("heartProg", instance); var arrestedProperty = type.GetProperty("inCardiacArrest", instance); var criticalProperty = type.GetProperty("isCriticallyDying", instance); var rate = rateProperty != null ? System.Convert.ToSingle(rateProperty.GetValue(display, null), System.Globalization.CultureInfo.InvariantCulture) : rateField != null ? System.Convert.ToSingle(rateField.GetValue(display), System.Globalization.CultureInfo.InvariantCulture) : -1f; stage = "rate"; var prog = progProperty != null ? System.Convert.ToSingle(progProperty.GetValue(display, null), System.Globalization.CultureInfo.InvariantCulture) : progField != null ? System.Convert.ToSingle(progField.GetValue(display), System.Globalization.CultureInfo.InvariantCulture) : -1f; stage = "prog"; var arrested = arrestedProperty == null ? "missing" : System.Convert.ToBoolean(arrestedProperty.GetValue(display, null)) ? "true" : "false"; stage = "arrested"; var critical = criticalProperty == null ? "missing" : System.Convert.ToBoolean(criticalProperty.GetValue(display, null)) ? "true" : "false"; stage = "critical"; var target = view.GetProperty("TargetSteamId", flags).GetValue(null, null); return "{\"ok\":true,\"stage\":\"" + stage + "\",\"open\":true,\"target\":\"" + target + "\",\"heartRate\":" + rate.ToString("0.#", System.Globalization.CultureInfo.InvariantCulture) + ",\"heartProg\":" + prog.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) + ",\"arrested\":\"" + arrested + "\",\"critical\":\"" + critical + "\"}"; } catch (System.Exception exception) { return "{\"ok\":false,\"stage\":\"" + stage + "\",\"error\":\"" + exception.GetType().Name + ": " + exception.Message.Replace("\"", "'") + "\"}"; } }))()